/* Walking monster easter egg (Alt+A) — Monster-Dev
   Sprite sheet assets/monster.png: 23 frames of 276 × 300 px, one gait cycle,
   faces left in the artwork (cut from 24 fps footage: 23/24 ≈ 0.96s). It travels
   left → right here, so the whole thing is mirrored via .monster-flip — shadow
   and sprite flip together, otherwise the shadow ends up under the wrong foot. */
.monster-walker {
  --frame-w: 184px;                      /* display width of a single frame */
  --frame-h: 200px;                      /* 300/276 × 184 → keeps the aspect ratio */
  --sheet-w: calc(var(--frame-w) * 23);
  --cycle: 0.96s;
  --stride: 130px;                       /* ground distance per gait cycle — the speed knob */
  --crossing: 16s;                       /* fallback; script.js derives the real value from --stride */

  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--frame-w);
  height: var(--frame-h);
  pointer-events: none;
  z-index: 999;
  display: none;
}

.monster-walker.is-walking {
  display: block;
  animation: monster-cross var(--crossing) linear 1 forwards;
}

.monster-flip {
  position: absolute;
  inset: 0;
  transform: scaleX(-1); /* artwork faces left; walking left → right needs it facing right */
}

.monster-shadow {
  position: absolute;
  right: 8%;
  bottom: 0;
  width: 42%;
  height: 10px;
  background: rgba(43, 43, 43, 0.2);
  border-radius: 50%;
  filter: blur(3px);
}

.monster-sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster.png");
  background-repeat: no-repeat;
  background-size: var(--sheet-w) var(--frame-h);
  animation: monster-walk-cycle var(--cycle) steps(23) infinite;
}

@keyframes monster-walk-cycle {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--sheet-w)) 0; }
}

@keyframes monster-cross {
  from { transform: translateX(calc(-1 * var(--frame-w))); }
  to   { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walker.is-walking {
    display: block;
    animation: none;
    left: calc(50vw - var(--frame-w) / 2);
  }
  .monster-sprite {
    animation: none;
  }
}

