const { chromium } = require('playwright');
const path = require('path');

const target = 'file://' + path.resolve(
  '<run>/index.html'
).replace(/\\/g, '/');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto(target);

  const before = await page.$eval('.monster-walker', el => getComputedStyle(el).display);
  console.log('before Alt+A, display:', before);

  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');

  await page.waitForTimeout(150);
  const walking = await page.$eval('.monster-walker', el => el.classList.contains('is-walking'));
  const displayNow = await page.$eval('.monster-walker', el => getComputedStyle(el).display);
  console.log('after Alt+A, is-walking:', walking, 'display:', displayNow);

  // mid-walk screenshot
  await page.waitForTimeout(1500);
  const transform1 = await page.$eval('.monster-walker', el => getComputedStyle(el).transform);
  await page.screenshot({ path: '/tmp/monster-egg-check/mid-walk.png' });
  console.log('mid-walk transform:', transform1);

  await page.waitForTimeout(1500);
  const transform2 = await page.$eval('.monster-walker', el => getComputedStyle(el).transform);
  console.log('later transform (should differ from mid-walk if still moving):', transform2);

  // re-trigger while walking should be ignored
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(50);
  const stillOneWalker = await page.$$eval('.monster-walker', els => els.length);
  console.log('walker element count (should stay 1):', stillOneWalker);

  // wait out the full crossing, then confirm it resets and can retrigger
  const crossing = await page.$eval('.monster-walker', el => parseFloat(getComputedStyle(el).getPropertyValue('--crossing')) * 1000);
  console.log('crossing duration (ms):', crossing);
  await page.waitForTimeout(Math.max(0, crossing - 3000) + 500);
  const afterFinish = await page.$eval('.monster-walker', el => el.classList.contains('is-walking'));
  console.log('after full crossing, is-walking (should be false):', afterFinish);

  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(150);
  const retriggered = await page.$eval('.monster-walker', el => el.classList.contains('is-walking'));
  console.log('re-trigger after finish works, is-walking:', retriggered);

  await browser.close();
})();

